package com.zizai.watermark;

/** Reads currently playing sources, including addresses set after page load. */
final class WebMediaScanner {
    static String script(){return "(function(){var media=[];function add(u,k,active){if(typeof u!=='string'||u.indexOf('https://')!==0)return;var old=media.find(x=>x.url===u&&x.kind===k);if(old){if(active)old.active=true;}else if(media.length<48)media.push({url:u,kind:k,active:!!active});}function scan(d){d.querySelectorAll('video,audio').forEach(x=>{var k=x.tagName==='AUDIO'?'AUDIO':'VIDEO';add(x.currentSrc,k,true);add(x.src,k,true);x.querySelectorAll('source').forEach(s=>add(s.src,k,true));});}scan(document);document.querySelectorAll('iframe').forEach(f=>{try{if(f.contentDocument)scan(f.contentDocument);}catch(e){}});performance.getEntriesByType('resource').slice(-128).forEach(x=>{try{var u=new URL(x.name),p=u.pathname.toLowerCase();if(/\\.(mp4|m4v|mov|webm|m3u8|mpd)$/.test(p))add(x.name,'VIDEO');else if(/\\.(mp3|m4a|aac|ogg|wav)$/.test(p))add(x.name,'AUDIO');else if(/(?:^|[.])(?:douyin|iesdouyin)[.]com$/.test(location.hostname||'')&&/(?:^|[.])douyinvod[.]com$/.test(u.hostname)&&(p.indexOf('/video/')>=0||/(?:^|&)mime_type=video(?:_|%2f|\\/)mp4(?:&|$)/i.test(u.search.slice(1))))add(x.name,'VIDEO');}catch(e){}});var s=window.__INITIAL_STATE__||{},id=(location.pathname.match(/\\/(?:explore|discovery\\/item)\\/([a-f0-9]+)/)||[])[1],n=s.noteData&&s.noteData.data&&s.noteData.data.noteData;if(!n&&s.note&&s.note.noteDetailMap&&id)n=(s.note.noteDetailMap[id]||{}).note;var dy=\"\";try{var di=(location.pathname.match(/\\/(?:video|note|share\\/video|share\\/slides)\\/(\\d+)/)||[])[1]||((location.search||'').match(/[?&](?:modal_id|aweme_id)=(\\d+)(?:&|$)/)||[])[1];function selected(o,d){if(!o||typeof o!=='object'||d>12)return null;if(String(o.aweme_id)===di)return o;var keys=Object.keys(o).slice(0,100);for(var key of keys){if(/recommend/i.test(key))continue;var found=selected(o[key],d+1);if(found)return found;}return null;}var item=di&&selected(window._ROUTER_DATA,0);if(!item){var rd=document.getElementById&&document.getElementById('RENDER_DATA');if(rd){var text=rd.textContent.trim();item=selected(JSON.parse(text[0]==='{'?text:decodeURIComponent(text)),0);}}if(item){var v=item.video||{};dy=JSON.stringify({item_list:[{aweme_id:item.aweme_id,desc:item.desc,is_private:item.is_private,is_prohibited:item.is_prohibited,video:{is_drm:v.is_drm,drm_type:v.drm_type,play_addr:v.play_addr,play_addr_h264:v.play_addr_h264,bit_rate:v.bit_rate},images:item.images,image_post_info:item.image_post_info}]});}}catch(e){}return JSON.stringify({douyin:dy,html:Array.from(document.querySelectorAll('title,meta,video,audio,source,script[type=\"application/ld+json\"]')).map(x=>x.outerHTML).join(''),state:n?JSON.stringify({noteData:{data:{noteData:n}}}):'',media:media});})()";}
}
